import sys

def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # lis[i] stores the maximum sum of increasing subsequence ending at i
    lis = [0] * n
    # lds[i] stores the maximum sum of decreasing subsequence starting at i
    lds = [0] * n

    # Compute lis
    for i in range(n):
        lis[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j] and lis[i] < lis[j] + arr[i]:
                lis[i] = lis[j] + arr[i]

    # Compute lds
    for i in range(n-1, -1, -1):
        lds[i] = arr[i]
        for j in range(i+1, n):
            if arr[i] > arr[j] and lds[i] < lds[j] + arr[i]:
                lds[i] = lds[j] + arr[i]

    # Find the maximum bitonic sum
    max_bitonic = 0
    for i in range(n):
        max_bitonic = max(max_bitonic, lis[i] + lds[i] - arr[i])

    return max_bitonic
